<script setup lang="ts">
/**
 * Table.Row: a row, a `<tr>`.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/table.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, inject } from 'vue'

import { useListening } from '@polymorph/vue'
import styles from '@polymorph/recipes/structure/table.module.css'

export interface TableRowProps {
  /**
   * Adds hover and a pointer cursor; the row's own primary cell still holds the link.
   */
  interactive?: boolean
  /**
   * Visual only in a table and semantic in a grid, because `aria-selected` belongs to a `grid`.
   * `undefined` is a third value. Rows that never set `aria-selected` mean the grid has no
   * selection, and `aria-selected="false"` means this row is outside an existing selection.
   * Defaulting to `false` would announce every plain table row as unselected, which tells the
   * reader nothing.
   */
  selected?: boolean
}

defineOptions({ name: 'TableRow', inheritAttrs: false })

withDefaults(defineProps<TableRowProps>(), { interactive: false, selected: undefined })
const emit = defineEmits<{ click: [] }>()
defineSlots<{ default?: (props: Record<string, never>) => unknown }>()
const listening = useListening()
const owner = inject<Record<string, any>>('polymorph:Table', {})
const open = computed(() => (event: KeyboardEvent) => {
  if (
    event.key !== 'Enter' ||
    !(event.target instanceof HTMLElement) ||
    !event.target.matches('th, td')
  )
    return
  event.preventDefault()
  emit('click')
})
</script>

<template>
  <tr
    :class="styles.row"
    :data-interactive="interactive ? '' : undefined"
    :data-selected="selected ? '' : undefined"
    :aria-selected="owner.grid && selected !== undefined ? selected : undefined"
    @click="interactive && emit('click')"
    @keydown="owner.grid && interactive && listening.click && open($event)"
  >
    <slot />
  </tr>
</template>
